<?php
require __DIR__.'/app/core.php'; require_login(true);
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); save_setting('home_page_id',(string)(int)$_POST['home_page_id']); save_setting('blog_page_id',(string)(int)$_POST['blog_page_id']); flash('Структура сайта сохранена.'); header('Location: '.url('site-structure.php')); exit; }
$pages=db()->query("SELECT id,title,slug FROM content WHERE type='page' ORDER BY title")->fetchAll(PDO::FETCH_ASSOC); $home=(int)setting('home_page_id','0');$blog=(int)setting('blog_page_id','0');
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?=url('assets/style.css')?>"><title>Структура сайта</title></head><body><main class="container"><p><a href="<?=url('admin')?>">← Админ-панель</a></p><h1>Главная страница и блог</h1><?php if($m=flash()):?><p class="notice"><?=e($m)?></p><?php endif;?><form method="post" class="card editor"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Главная страница<select name="home_page_id"><option value="0">Стандартная (slug: home)</option><?php foreach($pages as $page):?><option value="<?=$page['id']?>" <?=$home===$page['id']?'selected':''?>><?=e($page['title'])?> — /<?=e($page['slug'])?></option><?php endforeach;?></select></label><label>Страница блога<select name="blog_page_id"><option value="0">/blog (стандартный адрес)</option><?php foreach($pages as $page):?><option value="<?=$page['id']?>" <?=$blog===$page['id']?'selected':''?>><?=e($page['title'])?> — /<?=e($page['slug'])?></option><?php endforeach;?></select></label><p>Выбранная страница блога будет заменена автоматически списком опубликованных постов.</p><button>Сохранить</button></form></main></body></html>
